window.CP_CONTENT={"lessons": [{"id": 1, "area": "Seguridad", "title": "Antes de salir", "source": "09", "intro": "Revisa la bicicleta en un lugar seguro antes de empezar.", "checks": [["Comprueba el asentamiento de las ruedas", "Confiar solo en que la rueda gira"], ["Prueba ambos frenos antes de rodar", "Comprobarlos en la primera bajada"], ["Comprueba que la dirección gira libre y sin holgura", "Ignorar una holgura pequeña"], ["Lleva material acorde a la ruta", "Usar siempre una lista sin adaptarla"]], "practice": "Completa la lista antes de una salida y anota qué faltaba.", "practical": false}, {"id": 2, "area": "Seguridad", "title": "Tras un golpe", "source": "09", "intro": "El carbono necesita una inspección cuidadosa después de un impacto.", "checks": [["Una marca sospechosa requiere revisión", "La pintura siempre revela todo daño"], ["Un ruido nuevo merece investigación", "Tapar el ruido con lubricante"], ["No continúes si dudas de la integridad del cuadro", "Hacer otra bajada para comprobar"], ["Una inspección visual no descarta todo daño interno", "Una foto certifica la seguridad"]], "practice": "Localiza con la bici parada las zonas que inspeccionarías tras una caída.", "practical": true}, {"id": 3, "area": "Seguridad", "title": "Preparar una ruta", "source": "14", "intro": "La distancia por sí sola no describe la exigencia de una salida.", "checks": [["Valora desnivel y firme además de distancia", "Comparar rutas solo por kilómetros"], ["Planifica agua y escapatorias", "Improvisar el agua al final"], ["Adapta el recorrido a luz y meteorología", "La previsión no cambia el plan"], ["Un GPX no acredita transitabilidad", "Todo trazado descargado es seguro"]], "practice": "Prepara una ruta conocida con una alternativa corta.", "practical": false}, {"id": 4, "area": "Seguridad", "title": "Autonomía con cámara", "source": "17", "intro": "Tu Procaliber lleva cámaras: prepara la reparación correspondiente.", "checks": [["Lleva cámara de medida compatible", "Cualquier cámara sirve"], ["Revisa la causa del pinchazo antes de montar", "Cambiar la cámara sin buscar el objeto"], ["Comprueba el talón antes de inflar", "Inflar sin mirar el asentamiento"], ["Una llanta dañada puede impedir continuar", "La cámara compensa cualquier daño"]], "practice": "Identifica cámara, desmontables y bomba de tu kit sin desmontar nada.", "practical": true}, {"id": 5, "area": "Bicicleta y ajustes", "title": "Conoce tu montaje", "source": "02", "intro": "Separa lo que anuncia el catálogo de lo que está instalado.", "checks": [["Tu configuración del proyecto lleva tija rígida", "Lleva necesariamente la telescópica del catálogo"], ["Tubeless Ready describe preparación", "Significa que no hay cámara"], ["IsoBow pertenece al diseño del cuadro", "Es un amortiguador trasero ajustable"], ["Confirma la pieza exacta antes de comprar", "La marca basta para compatibilidad"]], "practice": "Relaciona cuadro, horquilla, transmisión y frenos con sus fichas.", "practical": false}, {"id": 6, "area": "Bicicleta y ajustes", "title": "Presión de neumáticos", "source": "17", "intro": "Presión, carcasa, llanta, carga y terreno trabajan juntos.", "checks": [["La presión máxima no es la recomendada", "Siempre se debe usar el máximo"], ["Con cámara importa el riesgo de pellizco", "Tiene el mismo comportamiento que tubeless"], ["Cambia una variable cada vez", "Cambiar varias evita confusiones"], ["Registra presión en frío y sensaciones", "La sensación sustituye al manómetro"]], "practice": "Registra una presión realmente medida, sin adoptar una cifra histórica.", "practical": true}, {"id": 7, "area": "Bicicleta y ajustes", "title": "Aire y SAG", "source": "12", "intro": "El SAG es el hundimiento bajo el peso equipado.", "checks": [["Mide con la horquilla abierta", "Medir bloqueada da el mismo resultado"], ["Usa bomba específica de suspensión", "Una bomba de neumático permite siempre ajuste fino"], ["Una presión de partida requiere comprobar SAG", "La tabla fija el ajuste definitivo"], ["La junta indica recorrido utilizado", "La junta roja siempre es una avería"]], "practice": "Identifica válvula, junta y bloqueo; consulta el procedimiento antes de medir.", "practical": false}, {"id": 8, "area": "Bicicleta y ajustes", "title": "Rebote y posición", "source": "12", "intro": "El rebote regula el retorno; los ajustes deben poder reproducirse.", "checks": [["Anota desde qué tope cuentas clics", "Un número sin referencia basta"], ["No fuerces el dial contra el tope", "Apretar fuerte mejora la precisión"], ["Cambia poco y prueba en lugar conocido", "Cambiar todo a la vez acelera el ajuste"], ["Una molestia persistente requiere valoración", "Seguir modificando indefinidamente es suficiente"]], "practice": "Anota tu configuración conocida indicando qué datos todavía faltan.", "practical": true}, {"id": 9, "area": "Mecánica", "title": "Limpieza por zonas", "source": "21", "intro": "Usar herramientas separadas evita arrastrar grasa a pintura y frenos.", "checks": [["Soft Washing corresponde a superficies pintadas", "Claw es el cepillo universal del cuadro"], ["Reserva Claw a la transmisión", "Úsalo después en los discos"], ["En barras usa paño limpio", "Frota barras con cerdas duras"], ["Evita chorro directo a retenes y rodamientos", "Cuanta más presión mejor"]], "practice": "Relaciona los cinco cepillos de la foto con sus zonas.", "practical": false}, {"id": 10, "area": "Mecánica", "title": "Lubricar con precisión", "source": "11", "intro": "La limpieza y el secado preceden a lubricar la cadena.", "checks": [["Lubrica la cadena según necesidad", "Engrasa cassette por fuera para proteger"], ["Retira el sobrante de lubricante", "Dejar exceso mejora siempre"], ["Mantén discos y pastillas libres de aceite", "Un poco de aceite elimina chirridos"], ["Separa paños de transmisión y frenos", "Un solo paño evita contaminación"]], "practice": "Prepara útiles limpios y señala qué piezas no deben recibir aceite.", "practical": true}, {"id": 11, "area": "Mecánica", "title": "Cambios que fallan", "source": "04", "intro": "Empieza por suciedad, rueda y daño visible antes de tocar ajustes.", "checks": [["Una rueda mal asentada puede alterar el cambio", "Solo el tensor causa fallos"], ["Tras golpe considera patilla doblada", "El tensor endereza la patilla"], ["No uses topes para corregir cualquier retraso", "Ajusta H y L ante cualquier ruido"], ["Detente si el cambio se acerca a radios", "Sigue pedaleando fuerte para probar"]], "practice": "Observa sin ajustar si el fallo aparece en una corona o en todas.", "practical": false}, {"id": 12, "area": "Mecánica", "title": "Frenos y cadena", "source": "20", "intro": "Distingue inspección, ajuste y operaciones que requieren experiencia.", "checks": [["La cadena Shimano indicada usa QUICK-LINK", "Se conecta con cualquier pasador"], ["Un cierre debe corresponder a esa cadena", "Todo cierre de 12 velocidades es idéntico"], ["No accionar freno con rueda fuera sin separador", "Apretar la maneta siempre ayuda"], ["Pérdida hidráulica requiere detener uso", "Basta con centrar la pinza"]], "practice": "Localiza manual de cadena y guía de frenos; identifica sus advertencias.", "practical": true}, {"id": 13, "area": "Técnica MTB", "title": "Posición y mirada", "source": "16", "intro": "Una posición móvil permite que la bicicleta absorba irregularidades.", "checks": [["Mira hacia la trayectoria prevista", "Fija la vista en la rueda"], ["Mantén brazos y piernas con movilidad", "Bloquea articulaciones para controlar"], ["Adapta reparto de peso al terreno", "Lleva el cuerpo siempre muy atrás"], ["Practica primero en terreno sencillo", "Aprende equilibrio en un obstáculo grande"]], "practice": "En zona llana despejada practica mirada y movilidad a baja velocidad.", "practical": false}, {"id": 14, "area": "Técnica MTB", "title": "Frenada progresiva", "source": "16", "intro": "Aprende a modular la frenada antes de aumentar dificultad.", "checks": [["Reduce velocidad antes de la curva", "Frena tarde dentro de la curva"], ["Modula para conservar adherencia", "Bloquear siempre frena mejor"], ["Practica ambos frenos de forma progresiva", "No utilices nunca el delantero"], ["Adapta velocidad a visibilidad y firme", "La bicicleta moderna elimina el riesgo"]], "practice": "Practica frenadas suaves en recta y terreno seguro, sin buscar velocidad.", "practical": true}, {"id": 15, "area": "Técnica MTB", "title": "Curvas y subidas", "source": "16", "intro": "Anticipación de mirada y desarrollo reduce correcciones bruscas.", "checks": [["Escoge desarrollo antes de gran carga", "Cambia siempre bajo máxima fuerza"], ["Mira la salida de la curva", "Mira solo el punto más cercano"], ["Busca cadencia sostenible", "Un desarrollo duro siempre es eficiente"], ["Aumenta dificultad gradualmente", "Superar un test autoriza cualquier sendero"]], "practice": "En una subida conocida practica anticipar un cambio sin buscar récord.", "practical": false}, {"id": 16, "area": "Técnica MTB", "title": "SPD y descalado", "source": "04", "intro": "La liberación debe practicarse antes de necesitarla con urgencia.", "checks": [["Practica con ambos pies en apoyo seguro", "Practica solo con el pie dominante"], ["Libera con anticipación al detenerte", "Espera a perder equilibrio"], ["Comprueba cala y tornillos ante problemas", "Compensa todo apretando tensión"], ["La tensión se adapta dentro del rango del pedal", "Forzar topes mejora el enganche"]], "practice": "Con apoyo estable y sin tráfico ensaya desenganche de ambos pies.", "practical": true}, {"id": 17, "area": "Equipo y datos", "title": "Polar y BSC200S", "source": "05", "intro": "Decide qué dispositivo será tu registro principal.", "checks": [["Evita duplicar actividades al importar", "Cada copia es una salida distinta"], ["El reloj puede registrar y medir FC", "El ciclocomputador hace innecesario todo registro"], ["Compartir FC requiere activar modo sensor compatible", "Aparece automáticamente en cualquier web"], ["Comprueba conexiones antes de iniciar", "Empareja durante una bajada"]], "practice": "Localiza el registro principal y comprueba las pantallas con la bici parada.", "practical": false}, {"id": 18, "area": "Equipo y datos", "title": "Magene S314", "source": "06", "intro": "Un sensor trabaja en velocidad o en cadencia, un modo cada vez.", "checks": [["Cadencia se mide desde la biela", "Se mide instalándolo en el manillar"], ["Velocidad usa montaje correspondiente en buje", "Cualquier posición mide velocidad"], ["Despierta el sensor antes de buscarlo", "Un sensor dormido siempre aparece"], ["Tras cambiar modo revisa emparejamiento", "El receptor reconoce siempre el cambio sin revisar"]], "practice": "Identifica dónde está instalado tu sensor y qué dato transmite.", "practical": true}, {"id": 19, "area": "Equipo y datos", "title": "Leer una salida", "source": "14", "intro": "Relaciona esfuerzo, terreno y sensaciones antes de valorar progreso.", "checks": [["La velocidad depende también de terreno y viento", "Toda subida de velocidad prueba mejora física"], ["RPE aporta contexto del esfuerzo", "Las sensaciones nunca cuentan"], ["No inventes potencia si no se midió", "La velocidad permite saber vatios exactos"], ["Compara recorridos y condiciones parecidas", "Cualquier salida sirve como referencia idéntica"]], "practice": "Registra una salida real con duración y sensaciones, sin completar huecos.", "practical": false}, {"id": 20, "area": "Equipo y datos", "title": "GPX y datos personales", "source": "07", "intro": "Un trazado no equivale a un entrenador ni a un mapa actualizado.", "checks": [["Un GPX puede carecer de altitud", "Todo GPX contiene desnivel fiable"], ["Las coordenadas pueden revelar domicilios", "Las rutas no son datos personales"], ["El perfil local vive en este navegador", "Se sincroniza por iniciar sesión en ChatGPT"], ["Exporta para trasladar tu progreso", "Publicar el sitio copia tus datos a otro móvil"]], "practice": "Importa un GPX conocido y comprueba qué campos contiene.", "practical": true}, {"id": 21, "area": "Preparación y recuperación", "title": "Esfuerzo sostenible", "source": "14", "intro": "La constancia y la progresión gradual importan más que una salida extrema.", "checks": [["Adapta volumen a capacidad de recuperación", "Más carga siempre mejora"], ["Combina datos con percepción de esfuerzo", "Un solo número manda siempre"], ["Reserva días de recuperación", "El descanso elimina todo progreso"], ["Una habilidad nueva se practica con margen", "Practicar fatigado es siempre mejor"]], "practice": "Anota cómo te sentiste antes y después de una salida habitual.", "practical": false}, {"id": 22, "area": "Preparación y recuperación", "title": "Fuerza complementaria", "source": "22", "intro": "El plan de bandas es material previo para revisar según tu situación actual.", "checks": [["Prioriza técnica antes de resistencia", "Usar todas las bandas es el objetivo inicial"], ["La resistencia de banda cambia con el estiramiento", "Su tensión es constante en todo recorrido"], ["Controla postura y respiración", "Compensa con balanceos"], ["Dolor nuevo o creciente exige detener y valorar", "El dolor confirma que el ejercicio funciona"]], "practice": "Revisa el montaje de la banda y el espacio; no aumentes carga por completar un test.", "practical": true}, {"id": 23, "area": "Preparación y recuperación", "title": "Agua y alimentación", "source": "14", "intro": "Prepara alimentación y bebida según duración, esfuerzo y condiciones.", "checks": [["Planifica acceso al agua", "El agua en ruta siempre está garantizada"], ["El calor cambia necesidades", "Usar idéntico plan en cualquier clima"], ["Prueba alimentos que toleras", "Estrena todo en la salida más exigente"], ["Una condición clínica requiere orientación individual", "La app sustituye asesoramiento profesional"]], "practice": "Antes de salir revisa agua disponible y duración prevista sin cálculos automáticos.", "practical": false}, {"id": 24, "area": "Preparación y recuperación", "title": "Recuperar y revisar", "source": "14", "intro": "El registro ayuda a detectar patrones, no a diagnosticar.", "checks": [["Registra sueño y sensaciones si aportan contexto", "Una cifra de sueño diagnostica enfermedad"], ["Reduce exigencia ante fatiga inusual", "Compensa fatiga acumulada con más intensidad"], ["Revisa equipo tras barro o lluvia", "Guardar mojada evita mantenimiento"], ["Una limitación persistente merece valoración", "La app puede certificar aptitud física"]], "practice": "Anota una observación útil después de salir y una mejora para la próxima vez.", "practical": true}], "procedures": [{"id": "limpieza", "title": "Limpieza completa con Muc-Off", "area": "Limpieza", "bike": "Procaliber", "level": "Básico · en casa", "source": "21", "page": 2, "tools": "Cinco cepillos Muc-Off, agua a baja presión, limpiador compatible y paños separados.", "steps": ["Retira barro suelto con agua a baja presión; evita dirigir chorros a retenes, pedalier y bujes.", "Usa Soft Washing en superficies pintadas; Wheel & Component en ruedas; Two Prong en huecos; Detailing en rincones. Reserva Claw a transmisión.", "Limpia las barras de la horquilla con paño limpio; no las frotes con cepillo duro.", "Aclara de forma controlada y seca. Lubrica la cadena cuando esté seca y retira el sobrante.", "Comprueba funcionamiento de los frenos y registra cualquier ruido o daño."], "avoid": "No llevar grasa de transmisión a discos, pastillas o cuadro. No lubricar cassette, plato y roldanas por fuera.", "stop": "Pérdida de frenada, fuga anormal o daño sospechoso en carbono: no continúes hasta revisar.", "photo": "cepillos-reales.jpg"}, {"id": "pinchazo", "title": "Pinchazo con cámara", "area": "Ruedas", "bike": "Ambas", "level": "Mecánica básica · en ruta", "source": "17", "page": 8, "tools": "Cámara compatible, bomba y desmontables adecuados.", "steps": ["Detente en un lugar seguro. Identifica rueda y tipo de eje antes de desmontar. No acciones el freno con rueda retirada sin separador.", "Desinfla del todo, destalona un lado con herramientas adecuadas y extrae la cámara.", "Revisa con cuidado cubierta y fondo de llanta. Retira la causa sin cortarte; una cámara nueva volverá a pinchar si queda el objeto.", "Da forma a la cámara con un poco de aire, coloca válvula y cámara sin pliegues, monta el talón evitando pellizcos.", "Infla gradualmente dentro de límites compatibles, comprueba asiento uniforme y monta la rueda según su procedimiento.", "Comprueba eje y freno antes de continuar. Consulta el manual del eje para su cierre; no improvises pares."], "avoid": "No asumir tubeless: tu montaje lleva cámaras. Evita usar metal que dañe cubierta, cámara o llanta.", "stop": "Talón roto, carcasa estructuralmente dañada, llanta fisurada o rueda insegura: no continuar."}, {"id": "cadena", "title": "Cadena fuera del plato", "area": "Transmisión", "bike": "Procaliber", "level": "Básico · en ruta", "source": "16", "page": 18, "tools": "Guantes y un apoyo estable.", "steps": ["Deja de pedalear y detente; evita apoyar la bicicleta sobre el cambio.", "Si necesitas liberar tensión, sitúa SHADOW RD+ en OFF y mueve la jaula suavemente.", "Localiza la cadena. Si está atrapada junto al carbono, no la arrastres ni fuerces.", "Recoloca eslabones sobre el plato y gira las bielas lentamente con la mano, manteniendo los dedos alejados de dientes y roldanas.", "Inspecciona el conjunto y vuelve a poner SHADOW RD+ en ON antes de rodar."], "avoid": "No pedalear con fuerza para que entre ni utilizar el tensor para ocultar daño.", "stop": "Cadena muy atrapada, grieta, patilla doblada o saltos persistentes: taller."}, {"id": "horquilla", "title": "Conocer aire, bloqueo y rebote", "area": "Suspensión", "bike": "Procaliber", "level": "Ajuste básico · en casa", "source": "12", "page": 2, "tools": "Bomba de suspensión, equipación habitual y registro de ajustes.", "steps": ["Identifica la Judy Gold Solo Air y consulta su referencia exacta antes de usar tablas de presión.", "Limpia barras y retenes; para medir SAG la horquilla debe estar abierta.", "Usa un apoyo seguro y equipación habitual para medir el hundimiento; registra la medida y la presión realmente usada.", "Ajusta una sola variable y prueba en terreno conocido. El rebote controla la velocidad de retorno.", "Cuenta clics indicando desde qué tope; no fuerces el dial. Mantén abierta la horquilla en terreno irregular."], "avoid": "Los 130 psi de la ficha son una propuesta histórica; no se presentan como presión actual. Cuatro clics sin referencia no reconstruyen un reglaje.", "stop": "Pérdidas anormales de aceite, holgura o funcionamiento impredecible: revisión profesional."}, {"id": "frenos", "title": "El freno roza: primeras comprobaciones", "area": "Frenos", "bike": "Ambas", "level": "Diagnóstico · en casa", "source": "11", "page": 10, "tools": "Apoyo estable y luz suficiente.", "steps": ["Antes de tocar la pinza, comprueba que la rueda está bien asentada y el eje correctamente fijado.", "Gira la rueda con cuidado y observa si el roce es continuo o aparece en un punto.", "El roce continuo puede orientar a centrado; el periódico puede orientar a un disco alabeado. Es una hipótesis, no una confirmación.", "Consulta el procedimiento del freno exacto antes de ajustar; nunca contamines disco o pastillas.", "Tras cualquier intervención comprueba giro y frenada a baja velocidad en lugar seguro."], "avoid": "No aplicar aceite para eliminar ruido ni abrir purgas para centrar la pinza.", "stop": "Fuga, pérdida de potencia, disco fisurado o dudas de fijación: detén el uso y acude al taller."}, {"id": "sensores", "title": "S314 sin señal", "area": "Dispositivos", "bike": "Ambas", "level": "Básico · en casa", "source": "06", "page": 2, "tools": "BSC200S y sensor instalado.", "steps": ["Mueve la biela o la rueda correspondiente para despertar el sensor.", "Comprueba si está configurado en cadencia o velocidad: solo funciona un modo cada vez.", "Busca por tipo e identificador en el BSC200S. No confundas la conexión con el teléfono y la conexión con el sensor.", "Si cambias modo o pila, revisa el emparejamiento según el manual. Comprueba montaje y posibles interferencias físicas.", "Prueba con la bicicleta parada antes de salir. Si persiste, inspecciona pila y sellado conforme al manual."], "avoid": "No prometer conexión automática del sensor con esta página web.", "stop": "No manipules dispositivos mirando la pantalla mientras ruedas."}]};